package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import cpw.mods.fml.common.*;import cpw.mods.fml.common.event.*;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;import net.minecraft.server.MinecraftServer;import net.minecraft.world.*;import net.minecraft.nbt.*;import net.minecraft.item.*;import net.minecraft.init.*;import net.minecraft.entity.*;import net.minecraftforge.common.util.*;import dev.industrialtechnology.core.*;import dev.industrialtechnology.railway.*;import dev.industrialtechnology.solar.*;import dev.industrialtechnology.capacitor.*;import dev.industrialtechnology.expansion.*;
@Mod(modid="industrialtech_rail_checks",name="Disposable solar railway checks",version="1",dependencies="required-after:industrialtech")
public final class RailServerChecks {
 private final List<String> report=new ArrayList<>();private int ticks,stage,failed;private WorldServer w;private EntityRollingStock engine,wagon,steam;private EntityRollingStock second,third,unloadWagon;private net.minecraft.inventory.IInventory unloadChest;private TileRailStation unloadStation;private TileSolar solar;private TileCapacitorBank bank;private TileRailStation charge,loader,unloader;private double begin;private int initialEnergy;private dev.industrialtechnology.quarry.TileQuarry quarry;private long minedAt;
 @Mod.EventHandler public void init(FMLInitializationEvent e){if(Boolean.getBoolean("industrialtech.railTest"))FMLCommonHandler.instance().bus().register(this);}
 private void test(String name,Runnable code){try{code.run();report.add("PASS: "+name);}catch(Throwable e){failed++;report.add("FAIL: "+name+" :: "+e);IndustrialTechnology.log.error(name,e);}}private static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 private TileTrack track(int x,int z,int f,int shape){w.getChunkFromChunkCoords(x>>4,z>>4);w.setBlock(x,70,z,RailwayRegistry.anchor,0,3);TileTrack t=(TileTrack)w.getTileEntity(x,70,z);t.facing=f;t.shape=shape;t.markDirty();TrackWorld.remove(t);TrackWorld.add(t);return t;}
 private TileSolar solar(int x,int z,int tier){w.getChunkFromChunkCoords(x>>4,z>>4);w.setBlock(x,80,z,RailwayRegistry.solar[tier],0,3);return(TileSolar)w.getTileEntity(x,80,z);}
 private TileRailStation station(int x,int y,int z,int type){w.setBlock(x,y,z,RailwayRegistry.stations[type],0,3);return(TileRailStation)w.getTileEntity(x,y,z);}
 @SubscribeEvent public void tick(TickEvent.ServerTickEvent event){if(event.phase!=TickEvent.Phase.END||!MinecraftServer.getServer().isDedicatedServer())return;if(++ticks<80&&stage==0)return;try{w=MinecraftServer.getServer().worldServerForDimension(0);if(stage==0){if(new File("rail-phase1.done").exists()){restart();finish(true);stage=99;return;}setup();stage=1;ticks=0;return;}if(stage==1){w.setWorldTime(6000);if(ticks==25){test("Four Ultimate photovoltaic cells generate 20480 RF/t and feed the actual bank",()->check(solar.network().members.size()==4&&solar.network().generation==20480&&bank.network().ledger.stored()>300000,"generation/bank "+bank.network().ledger.stored()+" members="+solar.network().members.size()+" gen="+solar.network().generation+" t="+w.getWorldTime()+" rain="+w.isRaining()));test("Rail cargo loader and unloader transfer ordinary stacks without overflow",()->{check(wagon.cargo.total()>0,"not loaded");check(loader.transferred>0,"loader inactive");check(unloadStation.transferred==47&&unloadWagon.cargo.total()==0,"unloader inactive");int count=0;for(int i=0;i<unloadChest.getSizeInventory();i++){ItemStack s=unloadChest.getStackInSlot(i);if(s!=null){check(s.stackSize<=s.getMaxStackSize(),"invalid ordinary output stack");count+=s.stackSize;}}check(count==47,"unloader-to-chest transaction "+count);check(loader.getStackInSlot(0)==null||loader.getStackInSlot(0).stackSize<=64,"oversized stack");});test("Station charges an actual electric locomotive with shared RF budget",()->check(engine.energy>0&&charge.transferred>0&&charge.snapshot().getInteger("TrainCapacity")==engine.capacity()&&charge.snapshot().getInteger("TrainRF")==engine.energy,"no charge/progress"));unloader=station(55,70,-3,2);engine.throttle=1;engine.brake=0;engine.energy=4000000;begin=engine.posX;initialEnergy=engine.energy;}
  if(ticks==150){test("Active entity tickets cover the whole consist and each loaded rail anchor",()->{com.google.common.collect.ImmutableSetMultimap<net.minecraft.world.ChunkCoordIntPair,net.minecraftforge.common.ForgeChunkManager.Ticket> chunks=net.minecraftforge.common.ForgeChunkManager.getPersistentChunksFor(w);for(EntityRollingStock e:engine.consist()){check(chunks.containsKey(new net.minecraft.world.ChunkCoordIntPair(((int)Math.floor(e.posX))>>4,((int)Math.floor(e.posZ))>>4)),"vehicle not forced");TileTrack t=TrackWorld.get(w,e.rail.track);check(t!=null&&chunks.containsKey(new net.minecraft.world.ChunkCoordIntPair(t.xCoord>>4,t.zCoord>>4)),"rail anchor not forced");}});test("Actual electric engine accelerates along track and consumes real RF",()->check(engine.posX>begin+5&&engine.speed>0&&engine.energy<initialEnergy,"motion "+engine.posX+" "+begin+" "+engine.status));test("Steam burns stored coal and builds real boiler heat",()->check(steam.fuel.count(0)<300&&steam.temperature>50&&steam.burn>0,"boiler"));engine.throttle=0;engine.brake=1;}
  if(ticks==450){test("Real optional mod cable routes charge electric trains from solar",()->RailPipeChecks.verify(s->report.add("PASS: "+s)));test("A connected wagon follows the engine by its own rail cursor",()->check(engine.rear.equals(wagon.getUniqueID())&&wagon.front.equals(engine.getUniqueID())&&Math.abs((engine.posX-wagon.posX)-16.8)<.05,"spacing"));test("Brakes stop the train without deleting cargo",()->check(engine.speed<.001,"braking"));steam.brake=0;setupQuarry();stage=2;ticks=0;}}if(stage==2){w.setWorldTime(6000);if(ticks==30)minedAt=quarry.mined;if(ticks==130){test("Warmed steam locomotive moves using pressure and consumes water",()->check(steam.posX>60&&steam.water<30000,"steam motion "+steam.posX+" "+steam.status));test("Real solar array -> capacitor -> Quarry sustains 100 blocks/second at 20 TPS",()->check(quarry.mined-minedAt==500,"mined="+(quarry.mined-minedAt)));quarry.toggleEnabled();persist();finish(false);stage=99;}}}catch(Throwable e){test("Harness setup",()->{throw new RuntimeException(e);});finish(false);stage=99;}}
 private void weather(float value){cpw.mods.fml.common.ObfuscationReflectionHelper.setPrivateValue(World.class,w,value,"rainingStrength","field_73004_o");cpw.mods.fml.common.ObfuscationReflectionHelper.setPrivateValue(World.class,w,value,"prevRainingStrength","field_73003_n");}
 private void setup(){try{RailPipeChecks.setup(w);}catch(Exception e){throw new RuntimeException(e);}w.setSpawnLocation(0,1,0);w.getGameRules().setOrCreateGameRule("doDaylightCycle","false");w.setWorldTime(6000);for(int x=0;x<=40;x++)for(int z=-2;z<=12;z++)w.getChunkFromChunkCoords(x,z);for(int x=0;x<=512;x+=16)track(x,0,0,0);for(int x=0;x<=128;x+=16)track(x,32,0,0);TileTrack curve=track(512,0,0,2);track(528,16,1,0);track(528,32,1,0);
  test("All five solar tiers ignore right-click and have no server GUI",()->{net.minecraft.entity.player.EntityPlayer p=net.minecraftforge.common.util.FakePlayerFactory.getMinecraft(w);net.minecraft.inventory.Container before=p.openContainer;for(int i=0;i<5;i++){int x=16+i*3;check(!RailwayRegistry.solar[i].onBlockActivated(w,x,80,60,p,1,.5f,.5f,.5f),"activation intercepted");check(p.openContainer==before,"panel opened a screen");check(IndustrialTechnology.proxy.getServerGuiElement(3,p,w,x,80,60)==null,"solar GUI route survived");}});
  test("All five solar tiers and all railway recipes register",()->{java.util.Set<net.minecraft.item.Item> outputs=new java.util.HashSet<>();for(Object recipe:net.minecraft.item.crafting.CraftingManager.getInstance().getRecipeList()){ItemStack out=((net.minecraft.item.crafting.IRecipe)recipe).getRecipeOutput();if(out!=null)outputs.add(out.getItem());}for(net.minecraft.block.Block block:RailwayRegistry.solar)check(outputs.contains(net.minecraft.item.Item.getItemFromBlock(block)),"solar recipe");for(Item item:RailwayRegistry.stockItems)check(outputs.contains(item),"stock recipe");for(Item item:RailwayRegistry.trackItems)check(outputs.contains(item),"track recipe");for(net.minecraft.block.Block block:RailwayRegistry.stations)check(outputs.contains(net.minecraft.item.Item.getItemFromBlock(block)),"station recipe");check(RailwayRegistry.solar.length==5&&RailwayRegistry.stockItems.length==6,"registry");for(int i=0;i<5;i++)check(solar(16+i*3,60,i).rate()==ExpansionConfig.solar[i],"tier");});
  test("Logical cargo uses three slots, 100 items / 300 coal and safe extraction",()->{LogicalCargo c=new LogicalCargo(3,false);for(int i=0;i<5;i++)c.insert(0,new ItemStack(Items.coal,64),64,false);check(c.count(0)==300&&Items.coal.getItemStackLimit()==64,"coal/global max");c.insert(1,new ItemStack(Blocks.stone,64),64,false);c.insert(1,new ItemStack(Blocks.stone,64),64,false);check(c.count(1)==100,"normal capacity");check(c.insert(1,new ItemStack(Items.diamond,1),1,false)==0,"type mixed");int total=0;ItemStack s;while((s=c.extract(0,300,false))!=null){check(s.stackSize<=64,"invalid extraction");total+=s.stackSize;}check(total==300,"coal loss");NBTTagList saved=c.save();LogicalCargo restored=new LogicalCargo(3,false);restored.load(saved);check(restored.count(1)==100,"save count");});
  test("Oversized and deeply nested item templates are rejected without consuming cargo",()->{LogicalCargo c=new LogicalCargo(3,false);ItemStack s=new ItemStack(Items.coal,64);NBTTagCompound n=new NBTTagCompound();n.setByteArray("huge",new byte[17000]);s.setTagCompound(n);check(c.insert(0,s,64,false)==0&&c.total()==0&&s.stackSize==64,"oversize");NBTTagCompound root=new NBTTagCompound(),at=root;for(int i=0;i<15;i++){NBTTagCompound child=new NBTTagCompound();at.setTag("nested",child);at=child;}s.setTagCompound(root);check(c.insert(0,s,64,false)==0,"depth");NBTTagList list=new NBTTagList();list.appendTag(new NBTTagString("ordinary"));NBTTagCompound good=new NBTTagCompound();good.setTag("list",list);s.setTagCompound(good);check(c.insert(0,s,1,false)==1,"valid list template rejected");});
  test("Three bounded high-entropy cargo templates round-trip the real legacy GUI packet",()->{EntityRollingStock e=new EntityRollingStock(w,StockType.FREIGHT,null,null);java.util.Random random=new java.util.Random(44);for(int i=0;i<3;i++){ItemStack s=new ItemStack(Items.dye,1,i);byte[] bytes=new byte[7300];random.nextBytes(bytes);NBTTagCompound tag=new NBTTagCompound();tag.setByteArray("Payload",bytes);s.setTagCompound(tag);check(e.cargo.insert(i,s,1,false)==1,"template rejected");}io.netty.buffer.ByteBuf b=io.netty.buffer.Unpooled.buffer();try{cpw.mods.fml.common.network.ByteBufUtils.writeTag(b,e.snapshot());check(b.readableBytes()<32767,"oversized legacy packet");NBTTagCompound tag=cpw.mods.fml.common.network.ByteBufUtils.readTag(b);check(tag.getTagList("Cargo",10).tagCount()==3,"packet lost bins");}finally{b.release();}});
  test("Cargo metadata and NBT identity stay separate; corrupt counts clamp",()->{LogicalCargo c=new LogicalCargo(3,false);ItemStack a=new ItemStack(Items.coal,64,0),b=new ItemStack(Items.coal,64,1);c.insert(0,a,64,false);check(c.insert(0,b,64,false)==0,"metadata");a.setTagCompound(new NBTTagCompound());a.getTagCompound().setString("Owner","x");check(c.insert(0,a,1,false)==0,"NBT merged");NBTTagList save=c.save();save.getCompoundTagAt(0).setInteger("Quantity",Integer.MAX_VALUE);c.load(save);check(c.count(0)==300,"corrupt count");});
  test("Rail distance cursor crosses joins and quarter curves continuously",()->{TileTrack t=(TileTrack)w.getTileEntity(496,70,0);TrackWorld.Cursor c=new TrackWorld.Cursor(t.id,0,15,1);double[] a=c.point(w);check(c.move(w,2),"join failed");check(Math.sqrt(RailPath.distance(c.point(w),a[0],a[1],a[2]))<2.01,"teleport");check(c.path(w).curve(),"not on curve");check(c.move(w,23)&&c.move(w,3),"curve exit");check(Math.abs(c.yaw(w))<1,"curve tangent");TrackWorld.Cursor reverse=c.copy();check(reverse.move(w,-26),"reverse traversal");});
  solar=solar(80,60,4);solar(81,60,4);solar(80,61,4);solar(81,61,4);w.setBlock(80,79,60,ModRegistry.capacitorBank,0,3);bank=(TileCapacitorBank)w.getTileEntity(80,79,60);
  test("Night and opaque roofs stop generation; weather reduces it",()->{TileSolar s=solar(96,60,4);w.setWorldTime(18000);check(s.sun()==0,"night");w.setWorldTime(6000);check(s.sun()>.99,"noon");w.setBlock(96,81,60,Blocks.stone,0,3);s.changed();check(s.sun()==0,"roof");w.setBlockToAir(96,81,60);s.changed();w.getWorldInfo().setRaining(true);weather(1);check(s.sun()<.5,"rain");w.getWorldInfo().setRaining(false);weather(0);});
  test("Solar RF queries and extraction simulations do not generate energy outside world ticks",()->{TileSolar s=solar(118,60,4);long stored=s.network().ledger.stored();for(int i=0;i<30;i++){s.getEnergyStored(ForgeDirection.DOWN);s.extractEnergy(ForgeDirection.DOWN,100,true);s.snapshot();}check(s.network().ledger.stored()==stored,"read generated RF");});
  test("Horizontal arrays preserve cached topology, split RF ownership and same-tick budgets",()->{TileSolar a=solar(110,60,4),b=solar(111,60,4),c=solar(112,60,4);SolarArrays.Array net=a.network();check(net.members.size()==3&&a.network()==net,"cache");long n=net.ledger.stored();w.setBlockToAir(111,80,60);check(a.network().members.size()==1&&c.network().members.size()==1,"split");check(a.network().ledger.stored()+c.network().ledger.stored()<=n,"RF duplicated");});
  engine=new EntityRollingStock(w,StockType.INDUSTRIAL,new TrackWorld.Cursor(((TileTrack)w.getTileEntity(64,70,0)).id,0,8,1),null);w.spawnEntityInWorld(engine);charge=station(72,70,3,0);charge.energy=1500000;
  wagon=new EntityRollingStock(w,StockType.FREIGHT,new TrackWorld.Cursor(((TileTrack)w.getTileEntity(48,70,0)).id,0,7.2,1),null);w.spawnEntityInWorld(wagon);loader=station(55,70,3,1);loader.setInventorySlotContents(0,new ItemStack(Items.coal,64));loader.setInventorySlotContents(1,new ItemStack(Items.iron_ingot,64));
  for(int x=0;x<=128;x+=16)track(x,64,0,0);unloadWagon=new EntityRollingStock(w,StockType.FREIGHT,new TrackWorld.Cursor(((TileTrack)w.getTileEntity(64,70,64)).id,0,8,1),null);w.spawnEntityInWorld(unloadWagon);unloadWagon.cargo.insert(0,new ItemStack(Items.iron_ingot,47),47,false);unloadStation=station(72,70,67,2);w.setBlock(73,70,67,Blocks.chest,0,3);unloadChest=(net.minecraft.inventory.IInventory)w.getTileEntity(73,70,67);
  steam=new EntityRollingStock(w,StockType.STEAM,new TrackWorld.Cursor(((TileTrack)w.getTileEntity(48,70,32)).id,0,8,1),null);w.spawnEntityInWorld(steam);for(int i=0;i<5;i++)steam.fuel.insert(0,new ItemStack(Items.coal,64),64,false);steam.water=30000;steam.throttle=1;steam.brake=1;
  test("Rail stock NBT preserves owner, custom inventories and energy, restores parked",()->{NBTTagCompound n=new NBTTagCompound();engine.energy=123456;engine.writeToNBT(n);EntityRollingStock copy=new EntityRollingStock(w);copy.readFromNBT(n);check(copy.energy==123456&&copy.speed==0&&copy.throttle==0&&copy.brake==1&&copy.rail.track.equals(engine.rail.track),"NBT");engine.energy=0;});
  second=new EntityRollingStock(w,StockType.FREIGHT,new TrackWorld.Cursor(((TileTrack)w.getTileEntity(32,70,0)).id,0,8.4,1),null);third=new EntityRollingStock(w,StockType.FREIGHT,new TrackWorld.Cursor(((TileTrack)w.getTileEntity(16,70,0)).id,0,9.6,1),null);w.spawnEntityInWorld(second);w.spawnEntityInWorld(third);
  test("Persistent physical couplings link a stopped engine to three freight wagons",()->{String result=RailCoupling.connect(engine,wagon,net.minecraftforge.common.util.FakePlayerFactory.getMinecraft(w));check(engine.rear!=null&&wagon.front!=null,"couple: "+result);check(RailCoupling.connect(wagon,second,net.minecraftforge.common.util.FakePlayerFactory.getMinecraft(w)).startsWith("Coupled"),"wagon2");check(RailCoupling.connect(second,third,net.minecraftforge.common.util.FakePlayerFactory.getMinecraft(w)).startsWith("Coupled"),"wagon3");check(engine.consist().size()==4,"three wagons missing");});
  test("Server ownership rejects foreign drivers, cargo access and coupling",()->{net.minecraftforge.common.util.FakePlayer a=net.minecraftforge.common.util.FakePlayerFactory.get(w,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"RailOwner")),b=net.minecraftforge.common.util.FakePlayerFactory.get(w,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"OtherDriver"));EntityRollingStock e=new EntityRollingStock(w,StockType.INDUSTRIAL,engine.rail.copy(),a.getUniqueID());e.riddenByEntity=a;e.control(b,0);check(e.throttle==0,"foreign throttle");check(!new ExpansionContainer(b,e,null).canInteractWith(b),"foreign cargo GUI");check(!RailCoupling.connect(e,wagon,b).startsWith("Coupled"),"foreign coupling");e.control(a,0);check(e.throttle>0,"owner throttle rejected");});
  test("RF charging does not bypass same-tick limits through repeated calls",()->{EntityRollingStock e=new EntityRollingStock(w,StockType.ACS64,engine.rail.copy(),null);check(e.charge(40000,false)==40000&&e.charge(40000,false)==10000&&e.charge(1,false)==0,"charge rate");});
 }
 private void setupQuarry(){int x=208,z=64;for(int dx=0;dx<16;dx++)for(int dz=0;dz<16;dz++)for(int y=1;y<=7;y++)w.setBlock(x+dx,y,z+dz,Blocks.stone,0,2);w.setBlock(x+8,8,z+8,ModRegistry.quarries[2],2,3);quarry=(dev.industrialtechnology.quarry.TileQuarry)w.getTileEntity(x+8,8,z+8);quarry.applySelection(dev.industrialtechnology.quarry.ChunkArea.CENTER);w.setBlock(x+7,8,z+8,ModRegistry.capacitorBank,0,3);for(int dx=0;dx<2;dx++)for(int dz=0;dz<2;dz++){w.setBlock(x+6+dx,9,z+8+dz,RailwayRegistry.solar[4],0,3);}quarry.toggleEnabled();}
 private void persist()throws Exception{engine.throttle=0;engine.brake=1;engine.speed=0;wagon.cargo.insert(2,new ItemStack(Items.diamond,37),37,false);w.saveAllChunks(true,null);Files.write(Paths.get("rail-phase1.done"),Arrays.asList(engine.getUniqueID().toString(),wagon.getUniqueID().toString()),StandardCharsets.UTF_8);}
 private void restart(){test("Real JVM restart restores persisted train entities, RF and logical cargo",()->{try{List<String> ids=Files.readAllLines(Paths.get("rail-phase1.done"),StandardCharsets.UTF_8);for(int x=0;x<40;x++)w.getChunkFromChunkCoords(x,0);EntityRollingStock e=RailwayWorld.get(w,UUID.fromString(ids.get(0))),c=RailwayWorld.get(w,UUID.fromString(ids.get(1)));check(e!=null&&c!=null,"entities missing");check(e.energy>0&&e.speed==0&&e.throttle==0,"RF/park");check(c.cargo.count(2)==37,"cargo persistence");}catch(Exception e){throw new RuntimeException(e);}});}
 private void finish(boolean restart){try{report.add("Failed: "+failed);Files.write(Paths.get("rail-"+(restart?"restart":"initial")+".txt"),report,StandardCharsets.UTF_8);}catch(Exception e){throw new RuntimeException(e);}MinecraftServer.getServer().initiateShutdown();}
}
